//! SQLite schema and open/migrate. WAL journal, full synchronous: the spike
//! measures truthfulness, not raw speed.
//!
//! Migration is stepwise (v1 then v2), each step one transaction, so a crash
//! mid-step rolls back and the step reruns cleanly on the next open. The
//! `GILUNE_SCHEMA_TARGET` env var lets the harness create genuinely old
//! databases; `fixtures/v1-vault` was generated by the actual v1 binary.

use crate::crashpoints::crashpoint;
use crate::{ids, Kernel};
use anyhow::Result;
use rusqlite::{Connection, Transaction};
use std::path::Path;

pub fn open_db(path: &Path) -> Result<Connection> {
    let conn = Connection::open(path)?;
    // journal_mode returns the resulting mode as a row, so query it.
    let _mode: String = conn.query_row("PRAGMA journal_mode = WAL", [], |r| r.get(0))?;
    conn.pragma_update(None, "synchronous", "FULL")?;
    conn.pragma_update(None, "foreign_keys", "ON")?;
    conn.busy_timeout(std::time::Duration::from_secs(10))?;
    Ok(conn)
}

pub fn schema_version(conn: &Connection) -> i64 {
    current_version(conn)
}

fn current_version(conn: &Connection) -> i64 {
    conn.query_row(
        "SELECT value FROM meta WHERE key = 'schema_version'",
        [],
        |r| r.get::<_, String>(0),
    )
    .ok()
    .and_then(|v| v.parse().ok())
    .unwrap_or(0)
}

fn schema_target() -> i64 {
    std::env::var("GILUNE_SCHEMA_TARGET")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(i64::MAX)
}

pub fn migrate(k: &mut Kernel) -> Result<()> {
    if current_version(&k.conn) < 1 {
        apply_v1(k)?;
    }
    if schema_target() < 2 {
        return Ok(());
    }
    if current_version(&k.conn) < 2 {
        apply_v2(k)?;
    }
    Ok(())
}

fn apply_v1(k: &mut Kernel) -> Result<()> {
    let tx = k.conn.transaction()?;
    tx.execute_batch(
        r#"
        CREATE TABLE IF NOT EXISTS meta (
            key TEXT PRIMARY KEY,
            value TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS objects (
            object_id TEXT PRIMARY KEY,
            type_id TEXT NOT NULL,
            schema_version INTEGER NOT NULL,
            class TEXT NOT NULL CHECK (class IN ('source','artifact','proposal')),
            origin_device TEXT NOT NULL,
            created_operation TEXT NOT NULL,
            display_created_at INTEGER NOT NULL,
            tombstone_json TEXT
        );
        CREATE TABLE IF NOT EXISTS revisions (
            revision_id TEXT PRIMARY KEY,
            object_id TEXT NOT NULL REFERENCES objects(object_id),
            based_on_json TEXT NOT NULL,
            payload_json TEXT NOT NULL,
            created_operation TEXT NOT NULL,
            created_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS heads (
            object_id TEXT NOT NULL REFERENCES objects(object_id),
            revision_id TEXT NOT NULL REFERENCES revisions(revision_id),
            PRIMARY KEY (object_id, revision_id)
        );
        CREATE TABLE IF NOT EXISTS operations (
            operation_id TEXT PRIMARY KEY,
            device_id TEXT NOT NULL,
            device_seq INTEGER NOT NULL,
            kind TEXT NOT NULL,
            target_id TEXT NOT NULL,
            committed_at INTEGER NOT NULL,
            UNIQUE (device_id, device_seq)
        );
        CREATE TABLE IF NOT EXISTS blobs (
            blob_id TEXT PRIMARY KEY,
            state TEXT NOT NULL CHECK (state IN ('committed','ready')),
            media_type TEXT NOT NULL,
            byte_len INTEGER NOT NULL,
            sha256 TEXT NOT NULL,
            rel_path TEXT NOT NULL,
            stage_id TEXT NOT NULL,
            created_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS blob_refs (
            blob_id TEXT NOT NULL REFERENCES blobs(blob_id),
            object_id TEXT NOT NULL REFERENCES objects(object_id),
            PRIMARY KEY (blob_id, object_id)
        );
        CREATE TABLE IF NOT EXISTS events (
            event_id TEXT PRIMARY KEY,
            event_type TEXT NOT NULL,
            schema_version INTEGER NOT NULL,
            transaction_id TEXT NOT NULL,
            producer TEXT NOT NULL,
            subject_object_id TEXT NOT NULL,
            subject_revision_id TEXT NOT NULL,
            causation_event_id TEXT,
            correlation_id TEXT NOT NULL,
            committed_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS subscriptions (
            subscription_id TEXT PRIMARY KEY,
            event_type TEXT NOT NULL,
            handler TEXT NOT NULL,
            enabled INTEGER NOT NULL DEFAULT 1
        );
        CREATE TABLE IF NOT EXISTS jobs (
            job_id TEXT PRIMARY KEY,
            event_id TEXT NOT NULL REFERENCES events(event_id),
            subscription_id TEXT NOT NULL REFERENCES subscriptions(subscription_id),
            handler TEXT NOT NULL,
            status TEXT NOT NULL CHECK (status IN ('pending','leased','completed','quarantined')),
            attempts INTEGER NOT NULL DEFAULT 0,
            lease_owner TEXT,
            lease_expires_at INTEGER,
            next_eligible_at INTEGER NOT NULL,
            last_error TEXT,
            processing_run_id TEXT,
            UNIQUE (event_id, subscription_id)
        );
        CREATE TABLE IF NOT EXISTS processing_runs (
            run_id TEXT PRIMARY KEY,
            idempotency_key TEXT NOT NULL UNIQUE,
            processor TEXT NOT NULL,
            processor_version TEXT NOT NULL,
            input_revisions_json TEXT NOT NULL,
            output_ids_json TEXT NOT NULL,
            status TEXT NOT NULL,
            finished_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS provenance (
            provenance_id TEXT PRIMARY KEY,
            artifact_object_id TEXT NOT NULL REFERENCES objects(object_id),
            run_id TEXT NOT NULL,
            inputs_json TEXT NOT NULL
        );
        CREATE TABLE IF NOT EXISTS vault_state (
            object_id TEXT PRIMARY KEY REFERENCES objects(object_id),
            rel_path TEXT NOT NULL,
            projected_revision TEXT NOT NULL,
            content_sha256 TEXT NOT NULL,
            missing INTEGER NOT NULL DEFAULT 0
        );
        CREATE TABLE IF NOT EXISTS quarantine_files (
            rel_path TEXT PRIMARY KEY,
            reason TEXT NOT NULL,
            seen_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS integrity_alerts (
            alert_id TEXT PRIMARY KEY,
            kind TEXT NOT NULL,
            subject TEXT NOT NULL,
            detail TEXT NOT NULL,
            raised_at INTEGER NOT NULL
        );
        "#,
    )?;
    // schema version + device identity
    tx.execute(
        "INSERT OR IGNORE INTO meta (key, value) VALUES ('schema_version', '1')",
        [],
    )?;
    tx.execute(
        "INSERT OR IGNORE INTO meta (key, value) VALUES ('device_id', ?1)",
        [ids::new_id()],
    )?;
    tx.commit()?;
    Ok(())
}

/// v2: operations carry self-describing payloads (the syncable statement),
/// events carry their origin device (processing-policy input), and per-device
/// sync frontiers exist. One transaction: crash mid-way rolls back whole.
fn apply_v2(k: &mut Kernel) -> Result<()> {
    let tx = k.conn.transaction()?;
    tx.execute_batch(
        r#"
        ALTER TABLE operations ADD COLUMN payload_json TEXT NOT NULL DEFAULT '{}';
        ALTER TABLE events ADD COLUMN origin_device TEXT NOT NULL DEFAULT '';
        CREATE TABLE sync_frontiers (
            device_id TEXT PRIMARY KEY,
            applied_seq INTEGER NOT NULL
        );
        "#,
    )?;
    // Backfill: every pre-v2 event originated on this device.
    tx.execute(
        "UPDATE events SET origin_device =
            (SELECT value FROM meta WHERE key = 'device_id')
         WHERE origin_device = ''",
        [],
    )?;
    crashpoint("migration.during");
    tx.execute(
        "UPDATE meta SET value = '2' WHERE key = 'schema_version'",
        [],
    )?;
    tx.commit()?;
    Ok(())
}

/// Record one operation with its self-describing payload — the syncable
/// statement of a durable change. Callers pass the payload that lets another
/// replica apply the change without any other context.
pub fn record_operation(
    tx: &Transaction,
    device_id: &str,
    kind: &str,
    target: &str,
    payload: &serde_json::Value,
    now: i64,
) -> Result<String> {
    let op_id = ids::new_id();
    let seq = next_device_seq(tx, device_id)?;
    tx.execute(
        "INSERT INTO operations (operation_id, device_id, device_seq, kind, target_id, payload_json, committed_at)
         VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7)",
        rusqlite::params![op_id, device_id, seq, kind, target, payload.to_string(), now],
    )?;
    Ok(op_id)
}

/// Test hook: create an object of an arbitrary (possibly unknown) type,
/// standing in for data from a device with a plugin this device lacks.
pub fn dev_add_object(
    k: &mut Kernel,
    type_id: &str,
    payload: &serde_json::Value,
) -> Result<String> {
    let now = Kernel::now_ms();
    let device = k.device_id.clone();
    let object_id = ids::new_id();
    let revision_id = ids::new_id();
    let tx = k.conn.transaction()?;
    {
        let op_payload = serde_json::json!({
            "object": { "object_id": &object_id, "type_id": type_id,
                        "schema_version": 1, "class": "artifact",
                        "display_created_at": now },
            "revision": { "revision_id": &revision_id, "based_on": [],
                          "payload": payload },
        });
        let op_id = record_operation(&tx, &device, "object-created", &object_id, &op_payload, now)?;
        tx.execute(
            "INSERT INTO objects (object_id, type_id, schema_version, class, origin_device, created_operation, display_created_at)
             VALUES (?1, ?2, 1, 'artifact', ?3, ?4, ?5)",
            rusqlite::params![object_id, type_id, device, op_id, now],
        )?;
        tx.execute(
            "INSERT INTO revisions (revision_id, object_id, based_on_json, payload_json, created_operation, created_at)
             VALUES (?1, ?2, '[]', ?3, ?4, ?5)",
            rusqlite::params![revision_id, object_id, payload.to_string(), op_id, now],
        )?;
        tx.execute(
            "INSERT INTO heads (object_id, revision_id) VALUES (?1, ?2)",
            rusqlite::params![object_id, revision_id],
        )?;
    }
    tx.commit()?;
    Ok(object_id)
}

/// Explicit user deletion: a tombstone operation that syncs like any other.
pub fn tombstone_object(k: &mut Kernel, object_id: &str) -> Result<()> {
    let now = Kernel::now_ms();
    let device = k.device_id.clone();
    let tombstone = serde_json::json!({ "at": now, "by": device });
    let tx = k.conn.transaction()?;
    {
        let op_payload = serde_json::json!({ "object_id": object_id, "tombstone": &tombstone });
        record_operation(&tx, &device, "tombstone", object_id, &op_payload, now)?;
        let n = tx.execute(
            "UPDATE objects SET tombstone_json = ?2 WHERE object_id = ?1",
            rusqlite::params![object_id, tombstone.to_string()],
        )?;
        anyhow::ensure!(n == 1, "no such object {object_id}");
    }
    tx.commit()?;
    Ok(())
}

pub fn device_id(conn: &Connection) -> Result<String> {
    Ok(conn.query_row(
        "SELECT value FROM meta WHERE key = 'device_id'",
        [],
        |r| r.get(0),
    )?)
}

/// Next per-device monotonic operation sequence (call inside a transaction).
pub fn next_device_seq(tx: &rusqlite::Transaction, device_id: &str) -> Result<i64> {
    let max: Option<i64> = tx.query_row(
        "SELECT MAX(device_seq) FROM operations WHERE device_id = ?1",
        [device_id],
        |r| r.get(0),
    )?;
    Ok(max.unwrap_or(0) + 1)
}

/// Internal invariants the harnesses assert after every recovery: nothing
/// reported saved may be unrecoverable, and operational state must be
/// self-consistent. Returns human-readable problems (empty = pass).
pub fn verify_invariants(k: &Kernel) -> Result<Vec<String>> {
    let count = |sql: &str| -> Result<i64> { Ok(k.conn.query_row(sql, [], |r| r.get(0))?) };
    let mut problems = Vec::new();

    for (blob_id, rel, sha) in crate::capture::blob_paths(k)? {
        let path = k.vault.join(&rel);
        match std::fs::read(&path) {
            Ok(bytes) => {
                if ids::sha256_hex(&bytes) != sha {
                    problems.push(format!("blob {blob_id} content hash mismatch"));
                }
            }
            Err(_) => problems.push(format!("blob {blob_id} file missing ({})", rel.display())),
        }
    }

    // No LOCAL blob may remain unpromoted after recovery unless an alert
    // says why; remote-pending blobs legitimately wait for sync chunks.
    let committed: i64 = count(
        "SELECT COUNT(*) FROM blobs WHERE state='committed' AND stage_id != 'remote'",
    )?;
    let missing_alerts: i64 = count(
        "SELECT COUNT(*) FROM integrity_alerts WHERE kind='missing-blob-bytes'",
    )?;
    if committed > missing_alerts {
        problems.push(format!(
            "{committed} unpromoted local blobs but only {missing_alerts} alerts"
        ));
    }

    // Every LOCAL-origin event has a job per enabled matching subscription
    // (remote-origin events are the origin device's work, not ours).
    let local_device = device_id(&k.conn)?;
    let missing_jobs: i64 = k.conn.query_row(
        "SELECT COUNT(*) FROM events e JOIN subscriptions s
             ON s.enabled = 1 AND s.event_type = e.event_type
         WHERE e.origin_device = ?1
           AND NOT EXISTS (SELECT 1 FROM jobs j
                           WHERE j.event_id = e.event_id
                             AND j.subscription_id = s.subscription_id)",
        [&local_device],
        |r| r.get(0),
    )?;
    if missing_jobs > 0 {
        problems.push(format!("{missing_jobs} committed local events lack jobs"));
    }

    let dangling: i64 = count(
        "SELECT COUNT(*) FROM jobs j WHERE j.status='completed'
           AND (j.processing_run_id IS NULL
                OR NOT EXISTS (SELECT 1 FROM processing_runs r
                               WHERE r.run_id = j.processing_run_id))",
    )?;
    if dangling > 0 {
        problems.push(format!("{dangling} completed jobs without runs"));
    }

    let dup_transcripts: i64 = count(
        "SELECT COALESCE(MAX(cnt), 0) FROM (
             SELECT COUNT(*) AS cnt FROM provenance p
             JOIN objects o ON o.object_id = p.artifact_object_id
             WHERE o.type_id = 'org.memory.transcription/transcript'
             GROUP BY p.inputs_json)",
    )?;
    if dup_transcripts > 1 {
        problems.push(format!(
            "duplicate transcripts for one input set (max {dup_transcripts})"
        ));
    }

    let headless: i64 = count(
        "SELECT COUNT(*) FROM objects o WHERE o.tombstone_json IS NULL
           AND NOT EXISTS (SELECT 1 FROM heads h WHERE h.object_id = o.object_id)",
    )?;
    if headless > 0 {
        problems.push(format!("{headless} live objects without heads"));
    }

    Ok(problems)
}

pub fn raise_alert(conn: &Connection, kind: &str, subject: &str, detail: &str) -> Result<()> {
    conn.execute(
        "INSERT INTO integrity_alerts (alert_id, kind, subject, detail, raised_at)
         VALUES (?1, ?2, ?3, ?4, ?5)",
        rusqlite::params![ids::new_id(), kind, subject, detail, Kernel::now_ms()],
    )?;
    Ok(())
}
